// Offline support for one TI Quick Budget app. Generated by build.py.
const CACHE = "tib-mint-202610100936";
const PREFIX = "tib-mint-";
const ASSETS = ["./", "index.html", "manifest.webmanifest", "icon-192.png", "icon-512.png", "apple-touch-icon.png", "favicon.png", "logo.png", "../lib/html2canvas.min.js", "../lib/jspdf.umd.min.js", "../lib/fonts/barlow-latin-400-normal.woff2", "../lib/fonts/barlow-latin-500-normal.woff2", "../lib/fonts/barlow-latin-600-normal.woff2", "../lib/fonts/barlow-semi-condensed-latin-500-normal.woff2", "../lib/fonts/barlow-semi-condensed-latin-600-normal.woff2", "../lib/fonts/barlow-semi-condensed-latin-700-normal.woff2"];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith(PREFIX) && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== location.origin) return;
  if (req.mode === "navigate") {
    // newest page when online, saved copy when offline
    e.respondWith(
      fetch(req).then(res => { const copy = res.clone(); caches.open(CACHE).then(c => c.put("index.html", copy)); return res; })
        .catch(() => caches.match("index.html"))
    );
    return;
  }
  e.respondWith(
    caches.match(req).then(hit => hit || fetch(req).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      return res;
    }))
  );
});
